  1→/**
  2→ * @cipherbox/sdk - Bin operations
  3→ *
  4→ * Extracted from: apps/web/src/services/bin.service.ts (962 LOC)
  5→ * All Zustand store access replaced with explicit parameters.
  6→ *
  7→ * Bin operations manage the recycle bin lifecycle:
  8→ * - addToBin: soft-delete (remove from folder, add to bin)
  9→ * - restoreFromBin: undo soft-delete (remove from bin, add back to folder)
 10→ * - permanentDeleteFromBin: hard-delete with CID cleanup
 11→ * - emptyBin: permanently delete all bin entries
 12→ * - loadBin: load current bin metadata from IPNS
 13→ *
 14→ * Each function takes explicit params instead of reading from stores.
 15→ */
 16→
 17→import type { SdkContext, TeeKeys } from '@cipherbox/sdk-core';
 18→import * as sdkCore from '@cipherbox/sdk-core';
 19→import {
 20→  encryptBinMetadata,
 21→  decryptBinMetadata,
 22→  deriveBinIpnsKeypair,
 23→  type BinEntry,
 24→  type RecycleBinMetadata,
 25→  type FolderChild,
 26→  type FilePointer,
 27→  type FolderEntry,
 28→} from '@cipherbox/core';
 29→import { bytesToHex, hexToBytes, wrapKey } from '@cipherbox/crypto';
 30→import type { FolderTree } from '../state/folder-tree';
 31→
 32→/** Current bin metadata version. */
 33→const BIN_METADATA_VERSION = 'v1' as const;
 34→
 35→/**
 36→ * Context for bin operations. Replaces Zustand store access.
 37→ */
 38→export type BinOperationContext = {
 39→  ctx: SdkContext;
 40→  userPrivateKey: Uint8Array;
 41→  userPublicKey: Uint8Array;
 42→  rootFolderKey: Uint8Array;
 43→  teeKeys?: TeeKeys;
 44→};
 45→
 46→/**
 47→ * Internal state for the bin (replaces useBinStore).
 48→ */
 49→export type BinState = {
 50→  entries: BinEntry[];
 51→  sequenceNumber: number;
 52→  ipnsName: string;
 53→};
 54→
 55→// ---------------------------------------------------------------------------
 56→// Internal helpers: load / save bin metadata
 57→// ---------------------------------------------------------------------------
 58→
 59→/**
 60→ * Load and decrypt bin metadata from IPNS.
 61→ */
 62→async function loadBinMetadataInternal(params: {
 63→  userPrivateKey: Uint8Array;
 64→  ctx: SdkContext;
 65→}): Promise<{
 66→  metadata: RecycleBinMetadata;
 67→  ipnsName: string;
 68→  sequenceNumber: bigint;
 69→} | null> {
 70→  const binIpns = await deriveBinIpnsKeypair(params.userPrivateKey);
 71→  const resolved = await sdkCore.resolveIpnsRecord(binIpns.ipnsName, params.ctx);
 72→
 73→  if (!resolved) return null;
 74→
 75→  const encryptedBytes = await sdkCore.fetchFromIpfs(params.ctx, resolved.cid);
 76→  const metadata = await decryptBinMetadata(encryptedBytes, params.userPrivateKey);
 77→
 78→  return {
 79→    metadata,
 80→    ipnsName: binIpns.ipnsName,
 81→    sequenceNumber: resolved.sequenceNumber,
 82→  };
 83→}
 84→
 85→/**
 86→ * Encrypt and publish bin metadata to IPNS.
 87→ */
 88→async function saveBinMetadata(params: {
 89→  metadata: RecycleBinMetadata;
 90→  binCtx: BinOperationContext;
 91→}): Promise<void> {
 92→  const binIpns = await deriveBinIpnsKeypair(params.binCtx.userPrivateKey);
 93→
 94→  // Encrypt metadata with user's public key (ECIES)
 95→  const encryptedBytes = await encryptBinMetadata(params.metadata, params.binCtx.userPublicKey);
 96→
 97→  // Pin to IPFS
 98→  const { cid } = await sdkCore.addToIpfs(params.binCtx.ctx, encryptedBytes);
 99→
100→  // TEE enrollment (optional)
101→  let encryptedIpnsKey: string | undefined;
102→  let keyEpoch: number | undefined;
103→
104→  if (params.binCtx.teeKeys?.currentPublicKey) {
105→    try {
106→      const teePublicKey = hexToBytes(params.binCtx.teeKeys.currentPublicKey);
107→      const wrappedKey = await wrapKey(binIpns.privateKey, teePublicKey);
108→      encryptedIpnsKey = bytesToHex(wrappedKey);
109→      keyEpoch = params.binCtx.teeKeys.currentEpoch;
110→    } catch {
111→      // TEE enrollment failure is non-blocking
112→    }
113→  }
114→
115→  // Publish IPNS record
116→  await sdkCore.createAndPublishIpnsRecord({
117→    ipnsPrivateKey: binIpns.privateKey,
118→    ipnsName: binIpns.ipnsName,
119→    metadataCid: cid,
120→    sequenceNumber: BigInt(params.metadata.sequenceNumber),
121→    encryptedIpnsPrivateKey: encryptedIpnsKey,
122→    keyEpoch,
123→    ctx: params.binCtx.ctx,
124→  });
125→}
126→
127→// ---------------------------------------------------------------------------
128→// Public API
129→// ---------------------------------------------------------------------------
130→
131→/**
132→ * Load the recycle bin metadata from IPNS.
133→ *
134→ * If no bin IPNS record exists yet (first login / never deleted anything),
135→ * returns an empty BinState so that deleteToBin can create the first record.
136→ * The old bin service handled this by creating in-memory-only empty state;
137→ * the SDK must do the same to avoid "Bin not loaded" errors on first delete.
138→ *
139→ * @returns Current bin state (never null — empty state if no record exists)
140→ */
141→export async function loadBin(params: { binCtx: BinOperationContext }): Promise<BinState> {
142→  const loaded = await loadBinMetadataInternal({
143→    userPrivateKey: params.binCtx.userPrivateKey,
144→    ctx: params.binCtx.ctx,
145→  });
146→
147→  if (!loaded) {
148→    // No bin IPNS record exists yet — return empty state.
149→    // The first addToBin call will create the IPNS record.
150→    const binIpns = await deriveBinIpnsKeypair(params.binCtx.userPrivateKey);
151→    return {
152→      entries: [],
153→      sequenceNumber: 0,
154→      ipnsName: binIpns.ipnsName,
155→    };
156→  }
157→
158→  return {
159→    entries: loaded.metadata.entries,
160→    sequenceNumber: loaded.metadata.sequenceNumber,
161→    ipnsName: loaded.ipnsName,
162→  };
163→}
164→
165→/**
166→ * Add item to recycle bin.
167→ *
168→ * Removes the item from the folder metadata (via deleteFromFolder),
169→ * creates a BinEntry, appends to bin metadata, and publishes both.
170→ *
171→ * @returns The removed item from the folder
172→ */
173→export async function addToBin(params: {
174→  folderIpnsName: string;
175→  childId: string;
176→  parentPath: string;
177→  folderTree: FolderTree;
178→  binState: BinState;
179→  binCtx: BinOperationContext;
180→}): Promise<{ removedItem: FolderChild; updatedBinState: BinState }> {
181→  const folder = params.folderTree.get(params.folderIpnsName);
182→  if (!folder) throw new Error('Folder not loaded');
183→
184→  // 1. Remove item from folder metadata
185→  const { updatedChildren, removedItem } = sdkCore.deleteFromFolder({
186→    children: folder.children,
187→    childId: params.childId,
188→  });
189→
190→  // 2. Publish updated folder metadata
191→  const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
192→    children: updatedChildren,
193→    folderKey: folder.folderKey,
194→    ipnsPrivateKey: folder.ipnsKeypair.privateKey,
195→    ipnsName: params.folderIpnsName,
196→    sequenceNumber: folder.sequenceNumber,
197→    ctx: params.binCtx.ctx,
198→  });
199→
200→  // 3. Update folder state
201→  folder.children = updatedChildren;
202→  folder.sequenceNumber = newSequenceNumber;
203→  folder.lastLoadedAt = Date.now();
204→  params.folderTree.set(params.folderIpnsName, folder);
205→
206→  // 4. Build bin entry
207→  const isFile = removedItem.type === 'file';
208→  const entry: BinEntry = {
209→    id: crypto.randomUUID(),
210→    itemType: isFile ? 'file' : 'folder',
211→    name: removedItem.name,
212→    originalParentIpnsName: params.folderIpnsName,
213→    originalPath: params.parentPath,
214→    deletedAt: Date.now(),
215→    size: 0,
216→    mimeType: '',
217→    filePointer: isFile ? (removedItem as FilePointer) : undefined,
218→    folderEntry: !isFile ? (removedItem as FolderEntry) : undefined,
219→  };
220→
221→  // 5. Update bin metadata and publish
222→  const updatedEntries = [...params.binState.entries, entry];
223→  const newBinSeq = params.binState.sequenceNumber + 1;
224→
225→  const metadata: RecycleBinMetadata = {
226→    version: BIN_METADATA_VERSION,
227→    sequenceNumber: newBinSeq,
228→    entries: updatedEntries,
229→  };
230→
231→  await saveBinMetadata({ metadata, binCtx: params.binCtx });
232→
233→  const updatedBinState: BinState = {
234→    entries: updatedEntries,
235→    sequenceNumber: newBinSeq,
236→    ipnsName: params.binState.ipnsName,
237→  };
238→
239→  return { removedItem, updatedBinState };
240→}
241→
242→/**
243→ * Restore an item from the recycle bin back to a folder.
244→ *
245→ * Removes the entry from bin metadata, adds the preserved FolderChild
246→ * back to the target folder's children, and publishes both.
247→ */
248→export async function restoreFromBin(params: {
249→  entryId: string;
250→  targetFolderIpnsName: string;
251→  folderTree: FolderTree;
252→  binState: BinState;
253→  binCtx: BinOperationContext;
254→}): Promise<{ restoredItem: FolderChild; updatedBinState: BinState }> {
255→  // 1. Find the bin entry
256→  const entry = params.binState.entries.find((e) => e.id === params.entryId);
257→  if (!entry) throw new Error('Bin entry not found');
258→
259→  // 2. Get the FolderChild to restore
260→  let child: FolderChild;
261→  if (entry.itemType === 'file' && entry.filePointer) {
262→    child = { ...entry.filePointer, modifiedAt: Date.now() };
263→  } else if (entry.itemType === 'folder' && entry.folderEntry) {
264→    child = { ...entry.folderEntry, modifiedAt: Date.now() };
265→  } else {
266→    throw new Error('Bin entry has no stored item reference');
267→  }
268→
269→  // 3. Add child back to target folder
270→  const targetFolder = params.folderTree.get(params.targetFolderIpnsName);
271→  if (!targetFolder) throw new Error('Target folder not loaded');
272→
273→  // Handle name collisions
274→  const existingNames = new Set(targetFolder.children.map((c) => c.name));
275→  if (existingNames.has(child.name)) {
276→    let newName = `${child.name} (restored)`;
277→    let counter = 2;
278→    while (existingNames.has(newName)) {
279→      newName = `${child.name} (restored ${counter})`;
280→      counter++;
281→    }
282→    child = { ...child, name: newName };
283→  }
284→
285→  const updatedFolderChildren = [...targetFolder.children, child];
286→
287→  // 4. Publish updated folder metadata
288→  const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
289→    children: updatedFolderChildren,
290→    folderKey: targetFolder.folderKey,
291→    ipnsPrivateKey: targetFolder.ipnsKeypair.privateKey,
292→    ipnsName: params.targetFolderIpnsName,
293→    sequenceNumber: targetFolder.sequenceNumber,
294→    ctx: params.binCtx.ctx,
295→  });
296→
297→  // 5. Update folder state
298→  targetFolder.children = updatedFolderChildren;
299→  targetFolder.sequenceNumber = newSequenceNumber;
300→  targetFolder.lastLoadedAt = Date.now();
301→  params.folderTree.set(params.targetFolderIpnsName, targetFolder);
302→
303→  // 6. Remove entry from bin and publish
304→  const remainingEntries = params.binState.entries.filter((e) => e.id !== params.entryId);
305→  const newBinSeq = params.binState.sequenceNumber + 1;
306→
307→  const metadata: RecycleBinMetadata = {
308→    version: BIN_METADATA_VERSION,
309→    sequenceNumber: newBinSeq,
310→    entries: remainingEntries,
311→  };
312→
313→  await saveBinMetadata({ metadata, binCtx: params.binCtx });
314→
315→  const updatedBinState: BinState = {
316→    entries: remainingEntries,
317→    sequenceNumber: newBinSeq,
318→    ipnsName: params.binState.ipnsName,
319→  };
320→
321→  return { restoredItem: child, updatedBinState };
322→}
323→
324→/**
325→ * Permanently delete a bin entry (unpin CIDs, remove from bin metadata).
326→ *
327→ * For files: unpins the content CID if available.
328→ * Does NOT handle recursive folder cleanup (that requires deep IPNS traversal).
329→ */
330→export async function permanentDeleteFromBin(params: {
331→  entryId: string;
332→  binState: BinState;
333→  binCtx: BinOperationContext;
334→}): Promise<{ updatedBinState: BinState }> {
335→  const entry = params.binState.entries.find((e) => e.id === params.entryId);
336→  if (!entry) throw new Error('Bin entry not found');
337→
338→  // Unpin content CID if available (best-effort)
339→  if (entry.contentCid) {
340→    try {
341→      await sdkCore.unpinFromIpfs(params.binCtx.ctx, entry.contentCid);
342→    } catch {
343→      // Best-effort CID cleanup
344→    }
345→  }
346→
347→  // Remove from bin metadata and publish
348→  const remainingEntries = params.binState.entries.filter((e) => e.id !== params.entryId);
349→  const newBinSeq = params.binState.sequenceNumber + 1;
350→
351→  const metadata: RecycleBinMetadata = {
352→    version: BIN_METADATA_VERSION,
353→    sequenceNumber: newBinSeq,
354→    entries: remainingEntries,
355→  };
356→
357→  await saveBinMetadata({ metadata, binCtx: params.binCtx });
358→
359→  return {
360→    updatedBinState: {
361→      entries: remainingEntries,
362→      sequenceNumber: newBinSeq,
363→      ipnsName: params.binState.ipnsName,
364→    },
365→  };
366→}
367→
368→/**
369→ * Empty the bin by permanently deleting all entries.
370→ *
371→ * Cleans up CIDs (best-effort) and publishes empty bin metadata.
372→ */
373→export async function emptyBin(params: {
374→  binState: BinState;
375→  binCtx: BinOperationContext;
376→}): Promise<{ updatedBinState: BinState }> {
377→  // Best-effort CID cleanup for each entry
378→  for (const entry of params.binState.entries) {
379→    if (entry.contentCid) {
380→      try {
381→        await sdkCore.unpinFromIpfs(params.binCtx.ctx, entry.contentCid);
382→      } catch {
383→        // Non-blocking
384→      }
385→    }
386→  }
387→
388→  // Publish empty bin metadata
389→  const newBinSeq = params.binState.sequenceNumber + 1;
390→  const metadata: RecycleBinMetadata = {
391→    version: BIN_METADATA_VERSION,
392→    sequenceNumber: newBinSeq,
393→    entries: [],
394→  };
395→
396→  await saveBinMetadata({ metadata, binCtx: params.binCtx });
397→
398→  return {
399→    updatedBinState: {
400→      entries: [],
401→      sequenceNumber: newBinSeq,
402→      ipnsName: params.binState.ipnsName,
403→    },
404→  };
405→}
