  1→/**
  2→ * SDK E2E Test Harness
  3→ *
  4→ * Creates authenticated CipherBoxClient instances backed by real API accounts.
  5→ * Extracted from packages/sdk/src/__tests__/integration.test.ts pattern.
  6→ *
  7→ * Each call to createTestContext() creates a unique user via /auth/test-login,
  8→ * initializes their vault, and returns a ready-to-use CipherBoxClient.
  9→ */
 10→
 11→import { CipherBoxClient } from '@cipherbox/sdk';
 12→import { initializeVault } from '@cipherbox/core';
 13→import { deriveIpnsName, hexToBytes, bytesToHex } from '@cipherbox/crypto';
 14→
 15→const API_URL = process.env.SDK_E2E_API_URL ?? 'http://localhost:3000';
 16→const SECRET = process.env.SDK_E2E_SECRET ?? 'e2e-test-secret-do-not-use-in-production';
 17→const THROTTLE_BYPASS = process.env.THROTTLE_BYPASS_SECRET ?? '';
 18→
 19→/**
 20→ * Build default headers for fetch calls.
 21→ * Includes the throttle bypass header when THROTTLE_BYPASS_SECRET is set.
 22→ */
 23→function fetchHeaders(extra: Record<string, string> = {}): Record<string, string> {
 24→  const headers: Record<string, string> = { ...extra };
 25→  if (THROTTLE_BYPASS) {
 26→    headers['X-Throttle-Bypass'] = THROTTLE_BYPASS;
 27→  }
 28→  return headers;
 29→}
 30→
 31→/** Default headers for the api-client axios instance (throttle bypass). */
 32→function axiosDefaultHeaders(): Record<string, string> | undefined {
 33→  return THROTTLE_BYPASS ? { 'X-Throttle-Bypass': THROTTLE_BYPASS } : undefined;
 34→}
 35→
 36→/** Core account data returned by createTestAccount (shared between sdk-e2e and load tests). */
 37→export interface TestAccount {
 38→  client: CipherBoxClient;
 39→  accessToken: string;
 40→  publicKey: Uint8Array;
 41→  privateKey: Uint8Array;
 42→  rootIpnsName: string;
 43→  rootFolderKey: Uint8Array;
 44→  rootIpnsKeypair: { publicKey: Uint8Array; privateKey: Uint8Array };
 45→  email: string;
 46→}
 47→
 48→export interface TestContext extends TestAccount {
 49→  /** Destroy the client and zero key material */
 50→  cleanup: () => void;
 51→}
 52→
 53→export interface CreateAccountOptions {
 54→  apiUrl?: string;
 55→  secret?: string;
 56→  label: string;
 57→  emailPrefix?: string;
 58→}
 59→
 60→/**
 61→ * Create a test account with an initialized vault and CipherBoxClient.
 62→ * This is the shared core used by both sdk-e2e (createTestContext) and
 63→ * load tests (createPoolClient).
 64→ */
 65→export async function createTestAccount(opts: CreateAccountOptions): Promise<TestAccount> {
 66→  const apiUrl = opts.apiUrl ?? API_URL;
 67→  const secret = opts.secret ?? SECRET;
 68→  const prefix = opts.emailPrefix ?? 'sdk-e2e';
 69→  const email = `${prefix}-${opts.label}-${Date.now()}@example.com`;
 70→
 71→  // 1. Authenticate
 72→  const loginRes = await fetch(`${apiUrl}/auth/test-login`, {
 73→    method: 'POST',
 74→    headers: fetchHeaders({ 'Content-Type': 'application/json' }),
 75→    body: JSON.stringify({ email, secret }),
 76→  });
 77→  if (!loginRes.ok) {
 78→    throw new Error(`test-login failed (${loginRes.status}): ${await loginRes.text()}`);
 79→  }
 80→  const { accessToken, publicKeyHex, privateKeyHex } = await loginRes.json();
 81→  const publicKey = hexToBytes(publicKeyHex);
 82→  const privateKey = hexToBytes(privateKeyHex);
 83→
 84→  // Steps 2-4 wrapped in try/catch to clean up the test account on failure
 85→  try {
 86→    // 2. Initialize vault
 87→    const vault = await initializeVault(privateKey);
 88→    const rootIpnsName = await deriveIpnsName(vault.rootIpnsKeypair.publicKey);
 89→
 90→    // 3. Register vault on server (v2: only ownerPublicKey + rootIpnsName, crypto lives in IPFS)
 91→    const initRes = await fetch(`${apiUrl}/vault/init`, {
 92→      method: 'POST',
 93→      headers: fetchHeaders({
 94→        Authorization: `Bearer ${accessToken}`,
 95→        'Content-Type': 'application/json',
 96→      }),
 97→      body: JSON.stringify({
 98→        ownerPublicKey: bytesToHex(publicKey),
 99→        rootIpnsName,
100→      }),
101→    });
102→    if (!initRes.ok) {
103→      throw new Error(`vault/init failed (${initRes.status}): ${await initRes.text()}`);
104→    }
105→
106→    // 4. Create CipherBoxClient with instance-scoped axios (no singleton needed)
107→    const client = new CipherBoxClient({
108→      apiUrl,
109→      getAccessToken: async () => accessToken,
110→      vaultKeypair: { publicKey, privateKey },
111→      rootIpnsName,
112→      rootFolderKey: vault.rootFolderKey,
113→      defaultHeaders: axiosDefaultHeaders(),
114→    });
115→    client.registerFolder(rootIpnsName, vault.rootFolderKey, vault.rootIpnsKeypair, [], 0n);
116→
117→    return {
118→      client,
119→      accessToken,
120→      publicKey,
121→      privateKey,
122→      rootIpnsName,
123→      rootFolderKey: vault.rootFolderKey,
124→      rootIpnsKeypair: vault.rootIpnsKeypair,
125→      email,
126→    };
127→  } catch (err) {
128→    // Clean up partially provisioned account to avoid leaks
129→    await deleteTestAccount({ accessToken }, apiUrl);
130→    throw err;
131→  }
132→}
133→
134→/**
135→ * Create a fully-initialized test context (convenience wrapper over createTestAccount).
136→ */
137→export async function createTestContext(label: string): Promise<TestContext> {
138→  const account = await createTestAccount({ label });
139→  return { ...account, cleanup: () => account.client.destroy() };
140→}
141→
142→/**
143→ * Delete a test account (cleanup after tests).
144→ */
145→export async function deleteTestAccount(
146→  ctx: { accessToken: string },
147→  apiUrl = API_URL
148→): Promise<void> {
149→  try {
150→    const res = await fetch(`${apiUrl}/auth/account`, {
151→      method: 'DELETE',
152→      headers: fetchHeaders({
153→        Authorization: `Bearer ${ctx.accessToken}`,
154→        'Content-Type': 'application/json',
155→      }),
156→      body: JSON.stringify({ confirmation: 'DELETE' }),
157→    });
158→    if (!res.ok) {
159→      console.warn(`Account deletion failed (${res.status}): ${await res.text()}`);
160→    }
161→  } catch (err) {
162→    console.warn(`Account deletion error: ${(err as Error).message}`);
163→  }
164→}
165→
166→/**
167→ * fetch() wrapper that automatically injects the throttle bypass header.
168→ * Use instead of raw fetch() in test suites to avoid 429s.
169→ */
170→export function testFetch(url: string, init?: RequestInit): Promise<Response> {
171→  const headers = new Headers(init?.headers);
172→  if (THROTTLE_BYPASS) {
173→    headers.set('X-Throttle-Bypass', THROTTLE_BYPASS);
174→  }
175→  return fetch(url, { ...init, headers });
176→}
177→
178→export { API_URL, SECRET, fetchHeaders };
