 1→/**
 2→ * Upload Throughput Scenario
 3→ *
 4→ * N clients each upload M files (1KB-500KB), measuring upload pipeline
 5→ * throughput including IPNS publish per file.
 6→ */
 7→
 8→import { describe, it, afterAll } from 'vitest';
 9→import {
10→  createClientPool,
11→  destroyClientPool,
12→  aggregateAndReport,
13→  type PoolClient,
14→} from '../harness/client-pool';
15→import { expectThresholdsPassed, type ThresholdConfig } from '../harness/thresholds';
16→import { runFileWorkload } from '../workloads/file-workload';
17→
18→const NUM_CLIENTS = parseInt(process.env.LOAD_TEST_CLIENTS ?? '10', 10);
19→const FILES_PER_CLIENT = 20;
20→
21→describe('Upload Throughput', () => {
22→  let pool: PoolClient[] = [];
23→
24→  afterAll(async () => {
25→    await destroyClientPool(pool);
26→  });
27→
28→  it(`${NUM_CLIENTS} clients × ${FILES_PER_CLIENT} files (1KB-500KB)`, async () => {
29→    pool = await createClientPool({
30→      clientCount: NUM_CLIENTS,
31→      label: 'upload-throughput',
32→    });
33→
34→    const results = await Promise.allSettled(
35→      pool.map((pc) => {
36→        pc.metrics.start();
37→        return runFileWorkload(pc, {
38→          fileCount: FILES_PER_CLIENT,
39→          minSize: 1_024,
40→          maxSize: 500 * 1_024,
41→          verifyDownloads: false,
42→        }).finally(() => pc.metrics.stop());
43→      })
44→    );
45→
46→    const succeeded = results.filter((r) => r.status === 'fulfilled').length;
47→    const failed = results.filter((r) => r.status === 'rejected').length;
48→    console.log(`\nClients completed: ${succeeded} succeeded, ${failed} failed`);
49→
50→    const metrics = await aggregateAndReport('Upload Throughput', pool);
51→
52→    // Threshold check: 2-3x observed baselines from Phase 19.2
53→    const THRESHOLDS: ThresholdConfig[] = [
54→      { operation: 'uploadFile', p95MaxMs: 10_000, errorRateMax: 0.05 },
55→    ];
56→
57→    expectThresholdsPassed(metrics, THRESHOLDS);
58→  });
59→});
