 1→/**
 2→ * @cipherbox/core - Device Registry Encryption
 3→ *
 4→ * ECIES encryption/decryption for the device registry blob.
 5→ * Uses the same wrapKey/unwrapKey primitives as folder key wrapping.
 6→ *
 7→ * Note: wrapKey/unwrapKey handle arbitrary-length data (not just 32-byte keys).
 8→ * eciesjs internally uses AES-256-GCM for the symmetric portion, so any
 9→ * length payload works. Overhead is ~97 bytes (65 ephemeral pubkey + 16 nonce + 16 tag).
10→ * A 10KB registry produces ~10.1KB ciphertext.
11→ */
12→
13→import { wrapKey, unwrapKey, CryptoError, clearBytes } from '@cipherbox/crypto';
14→import { validateDeviceRegistry } from './schema';
15→import type { DeviceRegistry } from './types';
16→
17→/**
18→ * Encrypt the device registry for IPFS storage.
19→ *
20→ * Serializes the registry to JSON and encrypts with ECIES using
21→ * the user's secp256k1 publicKey. Only the holder of the corresponding
22→ * privateKey can decrypt it.
23→ *
24→ * @param registry - The device registry to encrypt
25→ * @param userPublicKey - 65-byte uncompressed secp256k1 public key
26→ * @returns Encrypted registry blob
27→ */
28→export async function encryptRegistry(
29→  registry: DeviceRegistry,
30→  userPublicKey: Uint8Array
31→): Promise<Uint8Array> {
32→  const plaintext = new TextEncoder().encode(JSON.stringify(registry));
33→  try {
34→    return await wrapKey(plaintext, userPublicKey);
35→  } finally {
36→    clearBytes(plaintext);
37→  }
38→}
39→
40→/**
41→ * Decrypt the device registry from IPFS storage.
42→ *
43→ * Decrypts with ECIES using the user's secp256k1 privateKey,
44→ * parses the JSON, and validates the schema.
45→ *
46→ * @param encrypted - ECIES-encrypted registry blob from IPFS
47→ * @param userPrivateKey - 32-byte secp256k1 private key
48→ * @returns Validated DeviceRegistry
49→ * @throws CryptoError if decryption or validation fails
50→ */
51→export async function decryptRegistry(
52→  encrypted: Uint8Array,
53→  userPrivateKey: Uint8Array
54→): Promise<DeviceRegistry> {
55→  const plaintext = await unwrapKey(encrypted, userPrivateKey);
56→  try {
57→    const json = new TextDecoder().decode(plaintext);
58→    const parsed = JSON.parse(json);
59→    return validateDeviceRegistry(parsed);
60→  } catch (error) {
61→    if (error instanceof CryptoError) throw error;
62→    throw new CryptoError('Registry decryption produced invalid data', 'DECRYPTION_FAILED');
63→  } finally {
64→    clearBytes(plaintext);
65→  }
66→}
67→

  1→/**
  2→ * Device Registry Service
  3→ *
  4→ * Manages the encrypted device registry lifecycle: create for first device,
  5→ * load existing registry, register new devices, update heartbeats, encrypt,
  6→ * pin to IPFS, and publish via IPNS.
  7→ *
  8→ * Follows the same IPFS/IPNS patterns as folder.service.ts.
  9→ *
 10→ * IMPORTANT: Registry operations must NEVER block login.
 11→ * All errors are caught and logged, returning null on failure.
 12→ */
 13→
 14→import {
 15→  deriveRegistryIpnsKeypair,
 16→  encryptRegistry,
 17→  decryptRegistry,
 18→  type DeviceRegistry,
 19→  type DeviceEntry,
 20→  type DevicePlatform,
 21→} from '@cipherbox/core';
 22→import { bytesToHex, hexToBytes, wrapKey, type DeviceKeypair } from '@cipherbox/crypto';
 23→import { addToIpfs, fetchFromIpfs } from '../lib/api/ipfs';
 24→import { createAndPublishIpnsRecord, resolveIpnsRecord } from './ipns.service';
 25→import { useAuthStore } from '../stores/auth.store';
 26→
 27→/** Minimum interval between registry republishes for lastSeenAt-only changes (ms) */
 28→const HEARTBEAT_DEBOUNCE_MS = 5 * 60 * 1000; // 5 minutes
 29→
 30→/**
 31→ * Initialize or sync the device registry.
 32→ *
 33→ * This is the main entry point called during login. It handles:
 34→ * 1. Deriving the deterministic IPNS keypair from the user's privateKey
 35→ * 2. Resolving an existing registry from IPNS, or creating a new one
 36→ * 3. Adding/updating the current device in the registry
 37→ * 4. Encrypting, pinning to IPFS, and publishing via IPNS
 38→ * 5. Enrolling for TEE auto-republishing when teeKeys are available
 39→ *
 40→ * @returns Registry and IPNS name, or null if any step fails
 41→ */
 42→export async function initializeOrSyncRegistry(params: {
 43→  userPrivateKey: Uint8Array;
 44→  userPublicKey: Uint8Array;
 45→  deviceKeypair: DeviceKeypair;
 46→  deviceInfo: {
 47→    name: string;
 48→    platform: DevicePlatform;
 49→    appVersion: string;
 50→    deviceModel: string;
 51→    ipHash: string;
 52→  };
 53→}): Promise<{ registry: DeviceRegistry; ipnsName: string } | null> {
 54→  try {
 55→    // 1. Derive deterministic IPNS keypair for the registry
 56→    const registryIpns = await deriveRegistryIpnsKeypair(params.userPrivateKey);
 57→
 58→    // 2. Try to resolve existing registry
 59→    let registry: DeviceRegistry | null = null;
 60→    let needsPublish = true;
 61→
 62→    const resolved = await resolveIpnsRecord(registryIpns.ipnsName);
 63→
 64→    if (resolved) {
 65→      // Existing registry found -- fetch and decrypt
 66→      const encryptedBytes = await fetchFromIpfs(resolved.cid);
 67→      registry = await decryptRegistry(encryptedBytes, params.userPrivateKey);
 68→
 69→      // Snapshot before modification for change detection
 70→      const beforeJson = JSON.stringify(registry);
 71→
 72→      // Check if current device already exists
 73→      const existingDevice = registry.devices.find(
 74→        (d) => d.deviceId === params.deviceKeypair.deviceId
 75→      );
 76→
 77→      if (existingDevice) {
 78→        // Update existing device heartbeat and metadata
 79→        existingDevice.lastSeenAt = Date.now();
 80→        existingDevice.appVersion = params.deviceInfo.appVersion;
 81→        existingDevice.deviceModel = params.deviceInfo.deviceModel;
 82→      } else {
 83→        // New device -- register as pending
 84→        const newEntry = createEmptyDeviceEntry({
 85→          deviceKeypair: params.deviceKeypair,
 86→          deviceInfo: params.deviceInfo,
 87→          status: 'pending',
 88→        });
 89→        registry.devices.push(newEntry);
 90→      }
 91→
 92→      // Check if registry actually changed enough to warrant republish
 93→      // Avoid unnecessary republishes when only lastSeenAt changed recently
 94→      // (Pitfall 1 from RESEARCH.md: ECIES nondeterminism means every encrypt = new CID)
 95→      const afterJson = JSON.stringify(registry);
 96→      if (beforeJson === afterJson) {
 97→        // Nothing changed at all
 98→        needsPublish = false;
 99→      } else if (existingDevice) {
100→        // Device existed -- check if only heartbeat fields changed
101→        const beforeParsed = JSON.parse(beforeJson) as DeviceRegistry;
102→        const beforeDevice = beforeParsed.devices.find(
103→          (d) => d.deviceId === params.deviceKeypair.deviceId
104→        );
105→        if (beforeDevice) {
106→          const metadataChanged =
107→            beforeDevice.appVersion !== existingDevice.appVersion ||
108→            beforeDevice.deviceModel !== existingDevice.deviceModel;
109→          if (!metadataChanged) {
110→            // Only lastSeenAt changed -- apply debounce
111→            const timeSinceLastSeen = Date.now() - beforeDevice.lastSeenAt;
112→            if (timeSinceLastSeen < HEARTBEAT_DEBOUNCE_MS) {
113→              needsPublish = false;
114→            }
115→          }
116→        }
117→      }
118→    } else {
119→      // No existing registry -- first device, auto-authorized
120→      registry = {
121→        version: 'v1',
122→        sequenceNumber: 0,
123→        devices: [
124→          createEmptyDeviceEntry({
125→            deviceKeypair: params.deviceKeypair,
126→            deviceInfo: params.deviceInfo,
127→            status: 'authorized',
128→          }),
129→        ],
130→      };
131→    }
132→
133→    if (!needsPublish) {
134→      return { registry, ipnsName: registryIpns.ipnsName };
135→    }
136→
137→    // 5. Increment sequence number
138→    registry.sequenceNumber++;
139→
140→    // 6. Encrypt registry with user's public key
141→    const encryptedBytes = await encryptRegistry(registry, params.userPublicKey);
142→
143→    // 7. Pin to IPFS (cast to BlobPart; never use .buffer per CLAUDE.md)
144→    const { cid } = await addToIpfs(new Blob([encryptedBytes as BlobPart]));
145→
146→    // 8. Publish IPNS with TEE enrollment
147→    const teeKeys = useAuthStore.getState().teeKeys;
148→    let encryptedIpnsKey: string | undefined;
149→    let keyEpoch: number | undefined;
150→
151→    if (teeKeys?.currentPublicKey) {
152→      // ECIES-wrap the registry IPNS private key with TEE public key
153→      const wrappedKey = await wrapKey(
154→        registryIpns.privateKey,
155→        hexToBytes(teeKeys.currentPublicKey)
156→      );
157→      encryptedIpnsKey = bytesToHex(wrappedKey);
158→      keyEpoch = teeKeys.currentEpoch;
159→    }
160→
161→    await createAndPublishIpnsRecord({
162→      ipnsPrivateKey: registryIpns.privateKey,
163→      ipnsName: registryIpns.ipnsName,
164→      metadataCid: cid,
165→      sequenceNumber: BigInt(registry.sequenceNumber),
166→      encryptedIpnsPrivateKey: encryptedIpnsKey,
167→      keyEpoch,
168→    });
169→
170→    return { registry, ipnsName: registryIpns.ipnsName };
171→  } catch (error) {
172→    // Registry failures must NEVER block login
173→    console.error('[DeviceRegistry] Failed to sync registry:', error);
174→    return null;
175→  }
176→}
177→
178→/**
179→ * Load the registry from IPNS (read-only).
180→ *
181→ * Used by the polling hook (Plan 03) to check for remote changes.
182→ * Does NOT modify the registry -- just resolves, fetches, and decrypts.
183→ *
184→ * @returns Registry data with IPNS name and sequence number, or null on failure
185→ */
186→export async function loadRegistry(userPrivateKey: Uint8Array): Promise<{
187→  registry: DeviceRegistry;
188→  ipnsName: string;
189→  sequenceNumber: bigint;
190→} | null> {
191→  try {
192→    const registryIpns = await deriveRegistryIpnsKeypair(userPrivateKey);
193→    const resolved = await resolveIpnsRecord(registryIpns.ipnsName);
194→
195→    if (!resolved) {
196→      return null;
197→    }
198→
199→    const encryptedBytes = await fetchFromIpfs(resolved.cid);
200→    const registry = await decryptRegistry(encryptedBytes, userPrivateKey);
201→
202→    return {
203→      registry,
204→      ipnsName: registryIpns.ipnsName,
205→      sequenceNumber: resolved.sequenceNumber,
206→    };
207→  } catch (error) {
208→    console.error('[DeviceRegistry] Failed to load registry:', error);
209→    return null;
210→  }
211→}
212→
213→/**
214→ * Create a new DeviceEntry with all fields populated.
215→ *
216→ * Helper that constructs a complete entry for the registry.
217→ *
218→ * @param params.deviceKeypair - Device's Ed25519 keypair with device ID
219→ * @param params.deviceInfo - Device metadata from detectDeviceInfo + IP hash
220→ * @param params.status - Authorization status ('authorized' for first device, 'pending' for subsequent)
221→ * @returns Complete DeviceEntry ready to add to the registry
222→ */
223→export function createEmptyDeviceEntry(params: {
224→  deviceKeypair: DeviceKeypair;
225→  deviceInfo: {
226→    name: string;
227→    platform: DevicePlatform;
228→    appVersion: string;
229→    deviceModel: string;
230→    ipHash: string;
231→  };
232→  status: 'authorized' | 'pending';
233→}): DeviceEntry {
234→  const now = Date.now();
235→
236→  return {
237→    deviceId: params.deviceKeypair.deviceId,
238→    publicKey: bytesToHex(params.deviceKeypair.publicKey),
239→    name: params.deviceInfo.name,
240→    platform: params.deviceInfo.platform,
241→    appVersion: params.deviceInfo.appVersion,
242→    deviceModel: params.deviceInfo.deviceModel,
243→    ipHash: params.deviceInfo.ipHash,
244→    status: params.status,
245→    createdAt: now,
246→    lastSeenAt: now,
247→    revokedAt: null,
248→    revokedBy: null,
249→  };
250→}
