  1→/**
  2→ * Load Test Client Pool
  3→ *
  4→ * Manages N CipherBoxClient instances, each with its own test account.
  5→ * Creates accounts in parallel, distributes workloads, and collects metrics.
  6→ *
  7→ * Reuses the shared createTestAccount/deleteTestAccount from sdk-e2e
  8→ * to avoid duplicating the 5-step account provisioning sequence.
  9→ */
 10→
 11→import {
 12→  createTestAccount,
 13→  deleteTestAccount,
 14→  type TestAccount,
 15→} from '../../../sdk-e2e/src/fixtures/test-harness';
 16→import { MetricsCollector, type OperationMetrics } from './metrics';
 17→import { printSummary, toJsonReport } from './reporter';
 18→import {
 19→  KuboProvider,
 20→  PsaProvider,
 21→  PinataProvider,
 22→  type PinningProvider,
 23→  type PinningMode,
 24→  type ExternalProviderConfig,
 25→} from '@cipherbox/sdk-core';
 26→
 27→const API_URL = process.env.LOAD_TEST_API_URL ?? 'http://localhost:3000';
 28→const SECRET = process.env.LOAD_TEST_SECRET ?? 'e2e-test-secret-do-not-use-in-production';
 29→
 30→/** BYO external provider config from environment variables */
 31→export const BYO_ENDPOINT = process.env.BYO_IPFS_ENDPOINT; // e.g., https://api.pinata.cloud/psa
 32→export const BYO_AUTH_TOKEN = process.env.BYO_IPFS_AUTH_TOKEN ?? '';
 33→export const BYO_PROTOCOL = (process.env.BYO_IPFS_PROTOCOL ?? 'kubo') as 'kubo' | 'psa' | 'pinata';
 34→export const BYO_PROVIDER_NAME = process.env.BYO_IPFS_PROVIDER_NAME ?? 'external';
 35→
 36→export interface PoolClient extends TestAccount {
 37→  id: number;
 38→  metrics: MetricsCollector;
 39→}
 40→
 41→export interface ClientPoolOptions {
 42→  clientCount: number;
 43→  label: string;
 44→}
 45→
 46→/** Options for creating a pool of BYO-mode clients */
 47→export interface ByoPoolOptions extends ClientPoolOptions {
 48→  /** External provider config -- all BYO clients share this provider */
 49→  externalProvider: ExternalProviderConfig;
 50→  /** Pinning mode for BYO clients */
 51→  pinningMode: 'external' | 'dual';
 52→}
 53→
 54→/** A pool client augmented with BYO provider and mode */
 55→export interface ByoPoolClient extends PoolClient {
 56→  provider: PinningProvider;
 57→  pinningMode: PinningMode;
 58→  externalProvider: ExternalProviderConfig;
 59→}
 60→
 61→/**
 62→ * Create a pool of N authenticated CipherBoxClient instances.
 63→ *
 64→ * Each client has its own test account, vault, metrics collector, and
 65→ * instance-scoped axios (no shared singleton).
 66→ */
 67→export async function createClientPool(opts: ClientPoolOptions): Promise<PoolClient[]> {
 68→  const { clientCount, label } = opts;
 69→  console.log(`Creating ${clientCount} test accounts for "${label}"...`);
 70→  const start = performance.now();
 71→
 72→  // Create accounts in parallel batches of 5 to avoid overwhelming the API
 73→  const clients: PoolClient[] = [];
 74→  const batchSize = 5;
 75→
 76→  for (let batch = 0; batch < clientCount; batch += batchSize) {
 77→    const batchEnd = Math.min(batch + batchSize, clientCount);
 78→    const promises = [];
 79→
 80→    for (let i = batch; i < batchEnd; i++) {
 81→      promises.push(
 82→        createTestAccount({
 83→          apiUrl: API_URL,
 84→          secret: SECRET,
 85→          label: `${label}-${i}`,
 86→          emailPrefix: 'load',
 87→        }).then((account): PoolClient => ({ ...account, id: i, metrics: new MetricsCollector() }))
 88→      );
 89→    }
 90→
 91→    const results = await Promise.allSettled(promises);
 92→    for (const result of results) {
 93→      if (result.status === 'fulfilled') {
 94→        clients.push(result.value);
 95→      } else {
 96→        console.warn(`Failed to create pool client: ${result.reason}`);
 97→      }
 98→    }
 99→  }
100→
101→  const elapsed = performance.now() - start;
102→  console.log(
103→    `Created ${clients.length}/${clientCount} clients in ${(elapsed / 1000).toFixed(1)}s`
104→  );
105→
106→  return clients;
107→}
108→
109→/**
110→ * Destroy all clients in the pool and delete test accounts.
111→ */
112→export async function destroyClientPool(pool: PoolClient[]): Promise<void> {
113→  console.log(`Cleaning up ${pool.length} test accounts...`);
114→  for (const pc of pool) {
115→    pc.client.destroy();
116→    // Zero harness-owned key material (client.destroy() only clears its internal copies)
117→    pc.privateKey.fill(0);
118→    pc.rootFolderKey.fill(0);
119→    pc.rootIpnsKeypair.privateKey.fill(0);
120→    await deleteTestAccount(pc, API_URL);
121→  }
122→}
123→
124→/**
125→ * Create a pool of N BYO-mode authenticated CipherBoxClient instances.
126→ *
127→ * Each client has its own test account plus a PinningProvider instance
128→ * (KuboProvider or PsaProvider) for external pinning.
129→ *
130→ * Returns an empty array (with warning) if BYO_IPFS_ENDPOINT is not set,
131→ * allowing scenarios to skip gracefully.
132→ */
133→export async function createByoClientPool(opts: ByoPoolOptions): Promise<ByoPoolClient[]> {
134→  if (!BYO_ENDPOINT) {
135→    console.warn(
136→      'BYO_IPFS_ENDPOINT not set -- skipping BYO pool creation. ' +
137→        'Set BYO_IPFS_ENDPOINT, BYO_IPFS_AUTH_TOKEN, and optionally BYO_IPFS_PROTOCOL to run BYO scenarios.'
138→    );
139→    return [];
140→  }
141→
142→  const basePool = await createClientPool({
143→    clientCount: opts.clientCount,
144→    label: opts.label,
145→  });
146→
147→  const byoPool: ByoPoolClient[] = basePool.map((pc) => {
148→    let provider: PinningProvider;
149→    switch (opts.externalProvider.protocol) {
150→      case 'psa':
151→        provider = new PsaProvider(opts.externalProvider.endpoint, opts.externalProvider.authToken);
152→        break;
153→      case 'pinata':
154→        provider = new PinataProvider(
155→          opts.externalProvider.endpoint,
156→          opts.externalProvider.authToken
157→        );
158→        break;
159→      case 'kubo':
160→      default:
161→        provider = new KuboProvider(
162→          opts.externalProvider.endpoint,
163→          opts.externalProvider.authToken
164→        );
165→        break;
166→    }
167→
168→    return {
169→      ...pc,
170→      provider,
171→      pinningMode: opts.pinningMode,
172→      externalProvider: opts.externalProvider,
173→    };
174→  });
175→
176→  console.log(
177→    `BYO pool: ${byoPool.length} clients with ${opts.externalProvider.protocol} provider ` +
178→      `(mode: ${opts.pinningMode}, endpoint: ${opts.externalProvider.endpoint})`
179→  );
180→
181→  return byoPool;
182→}
183→
184→/**
185→ * Aggregate metrics from all pool clients, print summary, and return metrics.
186→ * Extracts the repeated boilerplate from every load test scenario.
187→ */
188→export async function aggregateAndReport(
189→  scenarioName: string,
190→  pool: PoolClient[]
191→): Promise<OperationMetrics[]> {
192→  const allMetrics = new MetricsCollector();
193→
194→  let minTimestamp = Infinity;
195→  let maxTimestamp = 0;
196→
197→  for (const pc of pool) {
198→    for (const sample of pc.metrics.getReadonlySamples()) {
199→      allMetrics.record(sample);
200→      if (sample.timestamp < minTimestamp) minTimestamp = sample.timestamp;
201→      if (sample.timestamp > maxTimestamp) maxTimestamp = sample.timestamp;
202→    }
203→  }
204→
205→  // Set collector timing from sample timestamps for accurate throughput calculation
206→  allMetrics.setElapsedMs(maxTimestamp > minTimestamp ? maxTimestamp - minTimestamp : 1);
207→
208→  const totalDuration = maxTimestamp > minTimestamp ? maxTimestamp - minTimestamp : 0;
209→  const metrics = allMetrics.getMetrics();
210→
211→  printSummary(scenarioName, metrics, totalDuration, pool.length);
212→
213→  // Write JSON report to file for CI artifact upload
214→  const reportJson = toJsonReport(scenarioName, metrics, totalDuration, pool.length);
215→  console.log('\nJSON Report:\n' + reportJson);
216→
217→  try {
218→    const fs = await import('node:fs/promises');
219→    const slug = scenarioName.toLowerCase().replace(/[^a-z0-9]+/g, '-');
220→    await fs.writeFile(`metrics-${slug}.json`, reportJson);
221→  } catch (err) {
222→    console.warn(`Failed to write metrics report: ${(err as Error).message}`);
223→  }
224→
225→  return metrics;
226→}
