  1→/**
  2→ * @cipherbox/core - Device Registry Schema Validation
  3→ *
  4→ * Runtime validation for DeviceRegistry JSON after decryption.
  5→ * Uses manual checks consistent with existing codebase patterns
  6→ * (see folder/metadata.ts validateFolderMetadata).
  7→ */
  8→
  9→import { CryptoError } from '@cipherbox/crypto';
 10→import type { DeviceRegistry, DeviceAuthStatus, DevicePlatform } from './types';
 11→
 12→const VALID_STATUSES: DeviceAuthStatus[] = ['pending', 'authorized', 'revoked'];
 13→const VALID_PLATFORMS: DevicePlatform[] = ['web', 'macos', 'linux', 'windows'];
 14→const HEX_REGEX = /^[0-9a-fA-F]+$/;
 15→
 16→/**
 17→ * Validate a parsed JSON object as a DeviceRegistry.
 18→ *
 19→ * Throws CryptoError with code 'DECRYPTION_FAILED' on validation failure
 20→ * to avoid leaking schema details to attackers.
 21→ *
 22→ * @param data - Unknown parsed JSON data
 23→ * @returns Validated DeviceRegistry
 24→ * @throws CryptoError if validation fails
 25→ */
 26→export function validateDeviceRegistry(data: unknown): DeviceRegistry {
 27→  if (typeof data !== 'object' || data === null) {
 28→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
 29→  }
 30→
 31→  const obj = data as Record<string, unknown>;
 32→
 33→  // Validate version
 34→  if (obj.version !== 'v1') {
 35→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
 36→  }
 37→
 38→  // Validate sequenceNumber
 39→  if (
 40→    typeof obj.sequenceNumber !== 'number' ||
 41→    !Number.isInteger(obj.sequenceNumber) ||
 42→    obj.sequenceNumber < 0
 43→  ) {
 44→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
 45→  }
 46→
 47→  // Validate devices array
 48→  if (!Array.isArray(obj.devices)) {
 49→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
 50→  }
 51→
 52→  // Validate each device entry
 53→  for (const device of obj.devices) {
 54→    validateDeviceEntry(device);
 55→  }
 56→
 57→  return data as DeviceRegistry;
 58→}
 59→
 60→/**
 61→ * Validate an individual device entry.
 62→ */
 63→function validateDeviceEntry(data: unknown): void {
 64→  if (typeof data !== 'object' || data === null) {
 65→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
 66→  }
 67→
 68→  const entry = data as Record<string, unknown>;
 69→
 70→  // Required string fields
 71→  const requiredStrings = [
 72→    'deviceId',
 73→    'publicKey',
 74→    'name',
 75→    'platform',
 76→    'appVersion',
 77→    'deviceModel',
 78→    'ipHash',
 79→    'status',
 80→  ];
 81→  for (const field of requiredStrings) {
 82→    if (typeof entry[field] !== 'string') {
 83→      throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
 84→    }
 85→  }
 86→
 87→  // Hex format + length validation for cryptographic fields
 88→  const deviceId = entry.deviceId as string;
 89→  if (deviceId.length !== 64 || !HEX_REGEX.test(deviceId)) {
 90→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
 91→  }
 92→
 93→  const publicKey = entry.publicKey as string;
 94→  if (publicKey.length !== 64 || !HEX_REGEX.test(publicKey)) {
 95→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
 96→  }
 97→
 98→  const ipHash = entry.ipHash as string;
 99→  if (ipHash.length !== 64 || !HEX_REGEX.test(ipHash)) {
100→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
101→  }
102→
103→  // Max length for free-text fields
104→  if ((entry.name as string).length > 200) {
105→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
106→  }
107→  if ((entry.appVersion as string).length > 50) {
108→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
109→  }
110→  if ((entry.deviceModel as string).length > 200) {
111→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
112→  }
113→
114→  // Validate status is a known value
115→  if (!VALID_STATUSES.includes(entry.status as DeviceAuthStatus)) {
116→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
117→  }
118→
119→  // Validate platform is a known value
120→  if (!VALID_PLATFORMS.includes(entry.platform as DevicePlatform)) {
121→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
122→  }
123→
124→  // Validate timestamp fields
125→  if (typeof entry.createdAt !== 'number' || typeof entry.lastSeenAt !== 'number') {
126→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
127→  }
128→
129→  // Validate nullable fields
130→  if (entry.revokedAt !== null && typeof entry.revokedAt !== 'number') {
131→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
132→  }
133→  if (entry.revokedBy !== null && typeof entry.revokedBy !== 'string') {
134→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
135→  }
136→}
