 1→/**
 2→ * @cipherbox/core - Device Registry Types
 3→ *
 4→ * Type definitions for the encrypted device registry stored on IPFS/IPNS.
 5→ * The registry tracks authenticated devices with rich metadata and supports
 6→ * cross-device approval (Phase 12.4).
 7→ */
 8→
 9→/** Authorization status for a device in the registry */
10→export type DeviceAuthStatus = 'pending' | 'authorized' | 'revoked';
11→
12→/** Platform identifier for a device */
13→export type DevicePlatform = 'web' | 'macos' | 'linux' | 'windows';
14→
15→/**
16→ * Individual device entry in the registry.
17→ *
18→ * Each entry represents a physical device that has authenticated
19→ * with the user's CipherBox account.
20→ */
21→export type DeviceEntry = {
22→  /** SHA-256 hash of device's Ed25519 public key (hex) */
23→  deviceId: string;
24→  /** Device's Ed25519 public key (hex) - for future key exchange in Phase 12.4 */
25→  publicKey: string;
26→  /** Human-readable device name (e.g., "Chrome on macOS") */
27→  name: string;
28→  /** Platform identifier */
29→  platform: DevicePlatform;
30→  /** App version string (e.g., "0.2.0") */
31→  appVersion: string;
32→  /** Device model or OS version (e.g., "macOS 15.2", "Chrome 123") */
33→  deviceModel: string;
34→  /** SHA-256 hash of IP address at registration (hex, privacy-preserving) */
35→  ipHash: string;
36→  /** Authorization status */
37→  status: DeviceAuthStatus;
38→  /** When device was first registered (Unix ms) */
39→  createdAt: number;
40→  /** Last time device synced with registry (Unix ms) */
41→  lastSeenAt: number;
42→  /** When device was revoked (Unix ms, null if not revoked) */
43→  revokedAt: number | null;
44→  /** Device ID of the device that performed revocation (null if not revoked) */
45→  revokedBy: string | null;
46→};
47→
48→/**
49→ * The full device registry.
50→ *
51→ * Encrypted as a single JSON blob with the user's publicKey via ECIES,
52→ * then stored on IPFS and referenced by a dedicated IPNS name.
53→ */
54→export type DeviceRegistry = {
55→  /** Schema version for future migrations */
56→  version: 'v1';
57→  /** Monotonically increasing update counter */
58→  sequenceNumber: number;
59→  /** Array of all device entries (including revoked, for audit trail) */
60→  devices: DeviceEntry[];
61→};
