 1→import { useCallback, useRef } from 'react';
 2→import { useInterval } from './useInterval';
 3→import { useVisibility } from './useVisibility';
 4→import { useOnlineStatus } from './useOnlineStatus';
 5→import { useDeviceRegistryStore } from '../stores/device-registry.store';
 6→import { useAuthStore } from '../stores/auth.store';
 7→import { loadRegistry } from '../services/device-registry.service';
 8→
 9→/** Polling interval for registry changes (independent from vault sync) */
10→const REGISTRY_SYNC_INTERVAL_MS = 60_000; // 60 seconds per CONTEXT.md
11→
12→/**
13→ * Polling hook for remote device registry changes.
14→ *
15→ * Runs independently from vault sync (different interval, different IPNS name).
16→ * Checks for remote registry changes every 60s, pausing when the tab is
17→ * backgrounded or the browser is offline.
18→ *
19→ * Does NOT fire an initial sync on mount -- Task 2 handles the initial load
20→ * via initializeOrSyncRegistry in the auth flow. This hook only handles
21→ * subsequent periodic checks.
22→ *
23→ * IMPORTANT (from MEMORY.md): Uses getState() inside async callbacks to
24→ * read fresh state, not hook selectors that capture stale closures.
25→ */
26→export function useDeviceRegistrySync(): void {
27→  const isVisible = useVisibility();
28→  const isOnline = useOnlineStatus();
29→
30→  // Guard against concurrent sync runs
31→  const isSyncingRef = useRef(false);
32→
33→  const doSync = useCallback(async () => {
34→    // Only sync when initialized (initial load via auth flow is complete)
35→    if (!useDeviceRegistryStore.getState().isInitialized) return;
36→
37→    // Read fresh state for privateKey (avoid stale closures)
38→    const privateKey = useAuthStore.getState().vaultKeypair?.privateKey;
39→    if (!privateKey) return; // Not logged in
40→
41→    // Skip if already syncing
42→    if (isSyncingRef.current) return;
43→    isSyncingRef.current = true;
44→
45→    try {
46→      const result = await loadRegistry(privateKey);
47→
48→      if (result) {
49→        const currentRegistry = useDeviceRegistryStore.getState().registry;
50→        const currentSeqNum = currentRegistry?.sequenceNumber ?? -1;
51→
52→        // Only update if remote has a newer sequence number
53→        if (result.registry.sequenceNumber > currentSeqNum) {
54→          useDeviceRegistryStore.getState().updateRegistry(result.registry);
55→        }
56→      }
57→    } catch (error) {
58→      const message = error instanceof Error ? error.message : 'Registry sync failed';
59→      useDeviceRegistryStore.getState().setSyncError(message);
60→    } finally {
61→      isSyncingRef.current = false;
62→    }
63→  }, []);
64→
65→  // Pause polling when backgrounded or offline
66→  const pollDelay = isVisible && isOnline ? REGISTRY_SYNC_INTERVAL_MS : null;
67→
68→  useInterval(doSync, pollDelay);
69→}
