 1→/**
 2→ * @cipherbox/core - Device Registry Encryption
 3→ *
 4→ * ECIES encryption/decryption for the device registry blob.
 5→ * Uses the same wrapKey/unwrapKey primitives as folder key wrapping.
 6→ *
 7→ * Note: wrapKey/unwrapKey handle arbitrary-length data (not just 32-byte keys).
 8→ * eciesjs internally uses AES-256-GCM for the symmetric portion, so any
 9→ * length payload works. Overhead is ~97 bytes (65 ephemeral pubkey + 16 nonce + 16 tag).
10→ * A 10KB registry produces ~10.1KB ciphertext.
11→ */
12→
13→import { wrapKey, unwrapKey, CryptoError, clearBytes } from '@cipherbox/crypto';
14→import { validateDeviceRegistry } from './schema';
15→import type { DeviceRegistry } from './types';
16→
17→/**
18→ * Encrypt the device registry for IPFS storage.
19→ *
20→ * Serializes the registry to JSON and encrypts with ECIES using
21→ * the user's secp256k1 publicKey. Only the holder of the corresponding
22→ * privateKey can decrypt it.
23→ *
24→ * @param registry - The device registry to encrypt
25→ * @param userPublicKey - 65-byte uncompressed secp256k1 public key
26→ * @returns Encrypted registry blob
27→ */
28→export async function encryptRegistry(
29→  registry: DeviceRegistry,
30→  userPublicKey: Uint8Array
31→): Promise<Uint8Array> {
32→  const plaintext = new TextEncoder().encode(JSON.stringify(registry));
33→  try {
34→    return await wrapKey(plaintext, userPublicKey);
35→  } finally {
36→    clearBytes(plaintext);
37→  }
38→}
39→
40→/**
41→ * Decrypt the device registry from IPFS storage.
42→ *
43→ * Decrypts with ECIES using the user's secp256k1 privateKey,
44→ * parses the JSON, and validates the schema.
45→ *
46→ * @param encrypted - ECIES-encrypted registry blob from IPFS
47→ * @param userPrivateKey - 32-byte secp256k1 private key
48→ * @returns Validated DeviceRegistry
49→ * @throws CryptoError if decryption or validation fails
50→ */
51→export async function decryptRegistry(
52→  encrypted: Uint8Array,
53→  userPrivateKey: Uint8Array
54→): Promise<DeviceRegistry> {
55→  const plaintext = await unwrapKey(encrypted, userPrivateKey);
56→  try {
57→    const json = new TextDecoder().decode(plaintext);
58→    const parsed = JSON.parse(json);
59→    return validateDeviceRegistry(parsed);
60→  } catch (error) {
61→    if (error instanceof CryptoError) throw error;
62→    throw new CryptoError('Registry decryption produced invalid data', 'DECRYPTION_FAILED');
63→  } finally {
64→    clearBytes(plaintext);
65→  }
66→}
