136→/**
137→ * Initialize or load the recycle bin on login.
138→ *
139→ * Derives the deterministic IPNS keypair, resolves existing bin metadata
140→ * from IPNS (or creates empty state), and populates the bin store.
141→ *
142→ * Non-blocking: errors are logged, not thrown.
143→ */
144→export async function initializeBin(params: {
145→  userPrivateKey: Uint8Array;
146→  userPublicKey: Uint8Array;
147→}): Promise<void> {
148→  const store = useBinStore.getState();
149→  store.setLoading(true);
150→
151→  try {
152→    // Reset TEE enrollment tracking for new session
153→    binTeeEnrolled = false;
154→
155→    // Try to load existing bin metadata (derives IPNS keypair internally)
156→    const loaded = await loadBinMetadata({ userPrivateKey: params.userPrivateKey });
157→
158→    // Set IPNS name from loaded result, or derive if no bin exists yet
159→    if (loaded) {
160→      store.setBinIpnsName(loaded.ipnsName);
161→    } else {
162→      const binIpns = await deriveBinIpnsKeypair(params.userPrivateKey);
163→      store.setBinIpnsName(binIpns.ipnsName);
164→    }
165→
166→    if (loaded) {
167→      store.setEntries(loaded.metadata.entries, loaded.metadata.sequenceNumber);
168→    } else {
169→      // No bin exists yet -- initialize with empty state
170→      store.setEntries([], 0);
171→    }
172→  } catch (error) {
173→    console.error('[Bin] Failed to initialize bin:', error);
174→    store.setError(error instanceof Error ? error.message : 'Failed to initialize bin');
175→    store.setLoading(false);
176→  }
177→}
