 1→/**
 2→ * Folder CRUD Workload
 3→ *
 4→ * Creates, renames, moves, and deletes folders.
 5→ */
 6→
 7→import type { PoolClient } from '../harness/client-pool';
 8→
 9→export interface FolderWorkloadOptions {
10→  /** Number of folder create-rename-delete cycles */
11→  cycles: number;
12→}
13→
14→/**
15→ * Run a folder CRUD workload on a single client.
16→ * Individual operation failures are recorded as errors but don't abort the workload.
17→ */
18→export async function runFolderWorkload(
19→  pc: PoolClient,
20→  opts: FolderWorkloadOptions
21→): Promise<void> {
22→  const { client, rootIpnsName, metrics } = pc;
23→
24→  for (let i = 0; i < opts.cycles; i++) {
25→    const name = `load-folder-${pc.id}-${i}`;
26→
27→    try {
28→      // Create
29→      const folder = await metrics.measure('createFolder', () =>
30→        client.createFolder(rootIpnsName, name)
31→      );
32→
33→      // Rename
34→      try {
35→        await metrics.measure('renameItem', () =>
36→          client.renameItem(rootIpnsName, folder.id, `${name}-renamed`)
37→        );
38→      } catch {
39→        /* non-fatal — continue to delete */
40→      }
41→
42→      // Delete
43→      try {
44→        await metrics.measure('deleteItem', () => client.deleteItem(rootIpnsName, folder.id));
45→      } catch {
46→        /* non-fatal */
47→      }
48→    } catch {
49→      /* create failed — skip rename and delete for this cycle */
50→    }
51→  }
52→}
